<?php
// Return scope is an item/quantity journal, independent of the original dispatch ledger.
function ri_scope_event($o){$id=(int)$o['id'];if(!isset($GLOBALS['RI_SCOPES'])){$GLOBALS['RI_SCOPES']=[];foreach(om_query("SELECT e.order_id,e.details_json FROM om_events e JOIN (SELECT MAX(id) id FROM om_events WHERE event_type='Return item scope' GROUP BY order_id) x ON x.id=e.id") as $e)$GLOBALS['RI_SCOPES'][(int)$e['order_id']]=json_decode($e['details_json'],true)?:[];}return $GLOBALS['RI_SCOPES'][$id]??null;}
function ri_line_units($line){$parts=$line['return_scope_parts']??[['qty'=>$line['qty'],'status'=>$line['status']??'','aftersales'=>$line['aftersales']??false,'return_qty'=>$line['return_qty']??'','item_tagged'=>array_key_exists('after_raw',$line)?(!in_array(norm($line['after_raw']),['','none','-','n/a','0'],true)||($line['status']??'')==='Return / Refund'):(!empty($line['aftersales'])||($line['status']??'')==='Return / Refund')]];$units=0;foreach($parts as $p){$v=trim((string)($p['return_qty']??''));$explicit=$v!==''&&!in_array(strtolower($v),['-','n/a','none'],true);if($explicit){if(!preg_match('/^\d+(?:\.0+)?$/D',$v))throw new Exception('Returned quantity is not a valid whole number. Verify the item quantity.');$q=(int)$v;if($q>(int)$p['qty'])throw new Exception('Returned quantity exceeds this source item quantity.');}else $q=($p['item_tagged']??(!empty($p['aftersales'])||($p['status']??'')==='Return / Refund'))?(int)$p['qty']:0;$units+=$q;}return $units;}
function ri_from_lines($o,$lines){$tot=[];foreach($lines as $l){$qty=ri_line_units($l);if(!$qty)continue;$c=$l['components']??null;if(!$c)return null;foreach($c as $x){$pid=(int)$x['product_id'];$tot[$pid]=($tot[$pid]??0)+$qty*(int)$x['per_bundle'];}}$original=om_existing_totals($o['id']);if(!$original)return null;foreach($tot as $pid=>$qty)if(!isset($original[$pid])||$qty>$original[$pid])throw new Exception('Tagged return quantity does not match the original dispatched item.');ksort($tot,SORT_NUMERIC);return $tot?:null;}
function ri_scope($o){$scope=ri_scope_event($o);if($scope)return $scope;if(oa_reported($o)['status']!=='Return / Refund')return null;$ev=om_query("SELECT upload_id FROM om_events WHERE order_id=? AND event_type='Platform status reported' ORDER BY id DESC LIMIT 1",[$o['id']])->fetch();$id=(int)($ev['upload_id']??0);if(!$id)return null;if(!array_key_exists($id,$GLOBALS['RI_SOURCE_UPLOADS']??[])){$b=om_query('SELECT meta_json,result_json FROM om_uploads WHERE id=?',[$id])->fetch();$GLOBALS['RI_SOURCE_UPLOADS'][$id]=$b?:null;}$b=$GLOBALS['RI_SOURCE_UPLOADS'][$id];if(!$b||!empty(json_decode($b['meta_json'],true)['manual']))return null;foreach(json_decode($b['result_json'],true)['validation']??[] as $row)if((string)$row['order']===(string)$o['order_no']){try{$tot=ri_from_lines($o,$row['lines']);}catch(Throwable $e){return null;}if($tot)return ['source'=>'Platform item tags','totals'=>$tot,'file_totals'=>$tot,'upload_id'=>$id,'snapshot'=>oa_reported($o)['snapshot']];}return null;}
function ri_save($o,$scope){om_event($o['id'],$scope['upload_id']??null,'Return item scope',$scope);$GLOBALS['RI_SCOPES'][(int)$o['id']]=$scope;}
function ri_report($o,$status,$snapshot,$upload,$lines){if($status!=='Return / Refund'||$lines===null)return;$b=$upload?om_query('SELECT meta_json FROM om_uploads WHERE id=?',[$upload])->fetch():null;if(!$b||!empty(json_decode($b['meta_json'],true)['manual']))return;$tot=ri_from_lines($o,$lines);if(!$tot)return;$old=ri_scope_event($o);if($old&&($old['source']??'')==='ICO selected items'&&($old['file_totals']??[])==$tot)return;if($old&&$old['totals']==$tot)return;ri_save($o,['source'=>'Platform item tags','totals'=>$tot,'file_totals'=>$tot,'upload_id'=>$upload,'snapshot'=>$snapshot,'stock_changed'=>false]);}
function ri_decorate_source($source,$o){if(!$o||oa_reported($o)['status']!=='Return / Refund')return $source;$scope=ri_scope($o);$source['return_scope']=['reported'=>true,'known'=>(bool)$scope,'totals'=>$scope['totals']??[],'source'=>$scope['source']??'Item selection required'];return $source;}
function ri_recommended($source){if(empty($source['return_scope']['known']))return [];$out=[];foreach($source['return_scope']['totals'] as $pid=>$qty){$item=$source['items'][$pid]??null;if($item&&$item['remaining']>0&&$qty>($item['returned']??0))$out[]=$item;}return $out;}
function ri_validate_row($row,$source){if(empty($source['return_scope']['reported']))return;if(!empty($row['return_items_only'])&&mb_strlen(trim($row['return_scope_reason']??''))<3)throw new Exception('Enter why this return/refund covers only the selected items and quantities.');if(!empty($source['return_scope']['known'])&&!isset($source['return_scope']['totals'][$row['product_id']])&&empty($row['return_items_only']))throw new Exception('This product is not tagged for return/refund. Confirm a verified actual return scope before adding other order items.');if(!empty($source['return_scope']['known'])&&empty($row['return_items_only'])){$limit=(int)($source['return_scope']['totals'][$row['product_id']]??0);$received=order_return_balance($row['platform'],$row['order'],$row['product_id'])['returned'];if($received+(int)($row['scope_received_sum']??$row['qty'])>$limit)throw new Exception('Received quantity exceeds the tagged return quantity. Verify the selected-item return scope before changing it.');}}
function ri_receipt($o,$batch){if(oa_reported($o)['status']!=='Return / Refund')return;$b=return_batch($batch);if($b['status']!=='Posted')return;$rows=array_values(array_filter(json_decode($b['rows_json'],true)?:[],fn($r)=>(string)($r['order']??'')===(string)$o['order_no']));if(!$rows||!array_filter($rows,fn($r)=>!empty($r['return_items_only'])))return;$old=ri_scope($o);if(($old['source_batch']??null)==$batch)return;$tot=[];foreach($rows as $r){if(empty($r['return_items_only'])||mb_strlen(trim($r['return_scope_reason']??''))<3)throw new Exception('Verify the same selected-item scope for this order.');$tot[(int)$r['product_id']]=order_return_balance($o['platform'],$o['order_no'],$r['product_id'])['returned'];}ksort($tot,SORT_NUMERIC);ri_save($o,['source'=>'ICO selected items','totals'=>$tot,'file_totals'=>$old['file_totals']??$old['totals']??om_existing_totals($o['id']),'snapshot'=>oa_reported($o)['snapshot'],'source_batch'=>$batch,'remarks'=>$rows[0]['return_scope_reason'],'confirmed_by'=>current_user()['id'],'stock_changed'=>false]);}
function ri_recheck_digest($o){$scope=ri_scope($o);$received=[];foreach($scope['totals']??[] as $pid=>$qty)$received[$pid]=order_return_balance($o['platform'],$o['order_no'],$pid)['returned'];return hash('sha256',json_encode([$o['id'],$o['revision'],$scope,$received]));}
function ri_recheck($o,$digest,$ack){if(!can_action('return_confirm')||!$ack)throw new Exception('Confirm review of the tagged items and existing posted receipts.');return process_transaction(function()use($o,$digest){$o=om_order($o['id'],true);$scope=ri_scope($o);if(!$scope||oa_reported($o)['status']!=='Return / Refund'||!oa_received_complete($o)||!hash_equals(ri_recheck_digest($o),(string)$digest))throw new Exception('Tagged items are not fully received or the review changed. No status or stock was changed.');ri_save($o,$scope+['verified_by'=>current_user()['id'],'remarks'=>'Verified existing tagged-item receipts; no quantity posted again','stock_changed'=>false]);oa_receipt_reconcile($o['platform'],$o['order_no']);om_event($o['id'],null,'Tagged return follow-up resolved',['totals'=>$scope['totals'],'stock_changed'=>false,'reason'=>'Only tagged items / quantities were expected; existing receipts already cover them.']);});}
function ri_recheck_panel(){if(!om_ready()||!can_action('return_confirm'))return;$rows=[];foreach(om_query("SELECT * FROM om_orders WHERE posting='Posted' AND monitoring<>'Resolved' ORDER BY id") as $o)if(oa_reported($o)['status']==='Return / Refund'&&ri_scope($o)&&oa_received_complete($o))$rows[]=$o;if(!$rows)return;echo '<section class="card"><h3>Tagged Return Items Already Received</h3><p>Other order items were not part of this return. Review the tagged quantities and link existing receipts without adding stock.</p>';foreach(array_slice($rows,0,20) as $o){$scope=ri_scope($o);echo '<div class="om-note"><b>'.e($o['platform'].' / '.$o['order_no']).'</b><ul>';foreach($scope['totals'] as $pid=>$qty){$p=om_query('SELECT master_sku,name FROM products WHERE id=?',[$pid])->fetch();echo '<li>'.e($p['master_sku'].' · '.$p['name']).' — '.$qty.' expected; '.order_return_balance($o['platform'],$o['order_no'],$pid)['returned'].' received</li>';}echo '</ul><form method="post" action="actions.php"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="receiving_resolve_item_scope"><input type="hidden" name="order_record_id" value="'.$o['id'].'"><input type="hidden" name="scope_digest" value="'.ri_recheck_digest($o).'"><label><input type="checkbox" name="scope_ack" value="1" required> I verified the tagged items and existing posted receipts.</label><button class="btn secondary">Resolve Tagged Return Follow-up · No Stock Change</button></form></div>';}echo '</section>';}
function ri_existing_plan($platform,$numbers,$lock=false){stock_platform($platform);if(!is_array($numbers)||!$numbers||count($numbers)>30)throw new Exception('Review 1 to 30 exact Order IDs.');$numbers=array_values(array_unique(array_map('strval',$numbers)));sort($numbers,SORT_STRING);$rows=[];foreach($numbers as $number){if(strlen($number)>100)throw new Exception('Order ID too long.');$o=om_find($platform,om_shops()[$platform],$number);$tot=[];$items=[];$reason='';if(!$o)$reason='Order not found in this database.';else{if($lock)$o=om_order($o['id'],true);if($o['posting']!=='Posted'||oa_reported($o)['status']!=='Return / Refund')$reason='Not an actively dispatched Return / Refund follow-up.';foreach(om_existing_totals($o['id']) as $pid=>$qty){$received=order_return_balance($platform,$o['order_no'],$pid)['returned'];if($received>0){$tot[$pid]=$received;$p=om_query('SELECT master_sku,name FROM products WHERE id=?',[$pid])->fetch();$items[]=['pid'=>$pid,'sku'=>$p['master_sku'],'name'=>$p['name'],'received'=>$received,'original'=>$qty];}if($received>$qty)$reason='Existing receipts exceed original dispatched quantity; investigate first.';}if(!$tot)$reason='No posted physical return items found.';}$rows[]=['number'=>$number,'order'=>$o?:null,'totals'=>$tot,'items'=>$items,'issue'=>$reason];}$p=['platform'=>$platform,'numbers'=>$numbers,'rows'=>$rows];$p['digest']=hash('sha256',json_encode($p));return $p;}
function ri_resolve_existing($platform,$numbers,$digest,$ack){if(!can_action('return_confirm')||!$ack)throw new Exception('Review and acknowledge the exact already-received items.');return process_transaction(function()use($platform,$numbers,$digest){$p=ri_existing_plan($platform,$numbers,true);if(!hash_equals($p['digest'],(string)$digest)||array_filter($p['rows'],fn($r)=>$r['issue']!==''))throw new Exception('Order / receipts changed or an order needs investigation. Review the current list.');foreach($p['rows'] as $row){$o=$row['order'];$old=ri_scope($o);if($o['monitoring']==='Resolved'&&($old['totals']??null)==$row['totals'])continue;ri_save($o,['source'=>'ICO selected items','totals'=>$row['totals'],'file_totals'=>$old['file_totals']??$old['totals']??om_existing_totals($o['id']),'snapshot'=>oa_reported($o)['snapshot'],'remarks'=>'Confirmed this return/refund covers only the already-posted items and quantities; other order items retained by customer','confirmed_by'=>current_user()['id'],'stock_changed'=>false]);oa_receipt_reconcile($platform,$o['order_no']);om_event($o['id'],null,'Existing partial return follow-up resolved',['totals'=>$row['totals'],'stock_changed'=>false,'reason'=>'Existing receipts linked; no return or stock movement posted again.']);}return count($p['rows']);});}
function ri_existing_panel(){if(empty($_GET['return_scope_orders'])||!can_action('return_confirm'))return;$raw=trim((string)$_GET['return_scope_orders']);$numbers=preg_split('/[\s,;]+/',$raw,-1,PREG_SPLIT_NO_EMPTY);$platform=$_GET['platform']??'Shopee';$p=ri_existing_plan($platform,$numbers);echo '<section class="card"><h3>Review Existing Partial Returns · No Stock Change</h3><p>Confirm only the posted item quantities shown below belong to these return/refund requests. Other items remain with the customer. This action does not receive or add stocks again.</p><table class="table"><tr><th>Order ID</th><th>Already posted return items</th><th>Review</th></tr>';foreach($p['rows'] as $row){echo '<tr><td>'.e($row['number']).'</td><td>';foreach($row['items'] as $item)echo '<div>'.e($item['sku'].' · '.$item['name']).' — '.$item['received'].' pcs received ('.$item['original'].' originally dispatched)</div>';echo '</td><td>'.e($row['issue']?:'Ready to link existing receipts').'</td></tr>';}echo '</table><form method="post" action="actions.php"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="receiving_resolve_existing_returns"><input type="hidden" name="platform" value="'.e($platform).'"><input type="hidden" name="numbers_json" value="'.e(json_encode($p['numbers'])).'"><input type="hidden" name="scope_digest" value="'.$p['digest'].'"><label><input type="checkbox" name="scope_ack" value="1" required> These posted items and quantities are the complete scope of these return/refund requests.</label><button class="btn primary" '.(array_filter($p['rows'],fn($r)=>$r['issue']!=='')?'disabled':'').'>Resolve Reviewed Returns · No Stock Addition</button></form></section>';}
